<script setup lang="ts">
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import { computed, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { usePreview, copy } from '../../features/preview/usePreviewStore';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const s=usePreview(), form=reactive(copy(s.models).map(m=>({...m,key:''}))),busy=ref<number|null>(null),checked=reactive<Record<number,boolean>>({}),error=ref('');
function options(index:number){return index===0?(form[index].provider==='DeepSeek'?['deepseek-chat','deepseek-reasoner']:['qwen-plus','qwen-max','qwen-turbo']):index===1?['text-embedding-v3','text-embedding-v4']:['gte-rerank-v2'];}
function providerChanged(i:number){form[i].model=options(i)[0];checked[i]=false;}
function save(){error.value='';for(let i=0;i<form.length;i++){const f=form[i];if(!f.model||(!f.configured&&!f.key.trim())){error.value=`请补充${f.role}模型与 API Key。`;return;}}form.forEach((f,i)=>{Object.assign(s.models[i],{provider:f.provider,model:f.model,configured:f.configured||!!f.key.trim(),tail:f.key.trim()?f.key.trim().slice(-4):f.tail});f.tail=s.models[i].tail;f.configured=s.models[i].configured;f.key='';});ElMessage.success('模型配置已更新');}
async function check(i:number){if(!form[i].model||(!form[i].configured&&!form[i].key.trim())){ElMessage.warning('请先填写模型与 API Key');return;}busy.value=i;checked[i]=false;await new Promise(r=>setTimeout(r,650));checked[i]=true;busy.value=null;}
const canEnable=computed(()=>s.models.every(m=>m.configured)&&s.effectiveDocs.value.length>0);
</script>
<template><div class="pv-page"><PageHeading title="AI 模型配置" description="配置 AI 回复与知识检索所需的模型，全店客服共用。" eyebrow="AI 与知识"/>
<div class="pv-card pv-service-card"><div class="pv-service-icon"><Icon name="MagicStick"/></div><div><h3>AI 自动接待</h3><p>开启后，AI 会自动回复客户消息。客服接入后，可在会话中单独开关 AI 回复建议。</p></div><el-switch v-model="s.aiEnabled.value" :disabled="!canEnable && !s.aiEnabled.value" aria-label="AI 自动接待"/></div>
<div v-if="!s.models.every(m=>m.configured)" class="pv-notice"><Icon name="InfoFilled"/><span>开启 AI 自动接待前，请先完成下方对话推理、向量化和重排序三个模型的配置。</span></div>
<form class="pv-card pv-model-settings" @submit.prevent="save"><div class="pv-panel-heading"><span class="pv-panel-meta">{{s.aiEnabled.value?'分别配置对话推理、向量化和重排序；API Key 可以共用，也可以分别填写。':'完成以下三个模型的配置，即可开启 AI 自动接待。'}}</span><div class="pv-card-actions"><button class="wb-btn primary" type="submit">保存配置</button></div></div><div class="pv-model-grid"><section v-for="(f,i) in form" :key="f.role" class="pv-card pv-model-card"><div class="pv-model-heading"><span class="pv-model-symbol" :class="['blue','purple','green'][i]"><Icon :name="i===0?'ChatLineRound':i===1?'Reading':'Connection'"/></span><div><h3>{{f.role}}</h3><p>{{['理解诉求、生成客服回复','将知识内容转换为检索向量','对召回的知识重新排序'][i]}}</p></div><span class="pv-tag" :class="f.configured?'green':'amber'">{{f.configured?'已配置':'待配置'}}</span></div><div class="pv-form"><label>服务商<PreviewSelect :aria-label="`${f.role}服务商`" v-model="f.provider" :disabled="i!==0" @change="providerChanged(i)"><option v-if="i===0">DeepSeek</option><option>百炼千问</option></PreviewSelect><small>{{i===0?'支持 DeepSeek 与百炼千问':'当前沿用百炼支持的模型适配'}}</small></label><label>模型<PreviewSelect :aria-label="`${f.role}模型`" v-model="f.model" @change="checked[i]=false"><option v-for="m in options(i)" :key="m">{{m}}</option></PreviewSelect></label><label>API Key<input v-model="f.key" type="password" autocomplete="new-password" :placeholder="`已配置 · •••• ${f.tail}（留空保持）`" @input="checked[i]=false"/><small>替换时填写；留空继续使用已配置的 Key</small></label><div class="pv-model-check"><button class="wb-btn" type="button" :disabled="busy===i" @click="check(i)"><Icon :name="busy===i?'Loading':'Connection'" :spin="busy===i"/>{{busy===i?'正在校验':'检查配置'}}</button><span v-if="checked[i]" class="pv-positive">配置完整</span></div></div></section></div></form><p v-if="error" class="wb-form-error" role="alert">{{error}}</p><p class="pv-muted pv-footnote">向量化模型变更后，需要重新生成知识向量，才能保持检索结果一致。</p>
</div></template>
